#include <sqlite3.h>
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <time.h>
#include "../../../lib/libbonfyre/include/bf_command_lookup.h"
#include <unistd.h>

typedef struct { char subject[512]; char scope[512]; } Closure;
static const char *arg(int argc,char **argv,const char *name){for(int i=2;i+1<argc;i++)if(!strcmp(argv[i],name))return argv[i+1];return NULL;}
static char *read_all(const char *path,size_t *n){FILE*f=fopen(path,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3*d,const char*q){char*e=NULL;int rc=sqlite3_exec(d,q,NULL,NULL,&e);if(rc!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static void jt(const char*s){putchar('"');for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static uint64_t hadd(uint64_t h,const char*s){for(const unsigned char*p=(const unsigned char*)(s?s:"");*p;p++){h^=*p;h*=1099511628211ULL;}h^=0xff;return h*1099511628211ULL;}
static int ensure_dir(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static int run_capture(const char*bin,char*const av[],const char*path){int fd,status=0;pid_t p;if(!bin||!*bin||!path||(fd=open(path,O_WRONLY|O_CREAT|O_TRUNC,0640))<0)return 0;p=fork();if(p<0){close(fd);return 0;}if(!p){if(dup2(fd,STDOUT_FILENO)<0)_exit(127);close(fd);execv(bin,av);_exit(127);}if(waitpid(p,&status,0)<0){close(fd);return 0;}if(fsync(fd)){close(fd);return 0;}close(fd);return WIFEXITED(status)&&WEXITSTATUS(status)==0;}
static int seen(sqlite3*d,const char*delta,const char*subject,const char*scope){sqlite3_stmt*s=NULL;int yes=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM scoped_reheat_receipt WHERE delta_id=?1 AND subject=?2 AND scope=?3",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,scope,-1,SQLITE_TRANSIENT);yes=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);return yes;}
static int add_receipt(sqlite3*d,const char*delta,const char*subject,const char*scope,const char*closure){sqlite3_stmt*s=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT OR IGNORE INTO scoped_reheat_receipt(delta_id,subject,scope,closure_path,processed_at) VALUES(?1,?2,?3,?4,?5)",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,scope,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,closure,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,5,(sqlite3_int64)time(NULL));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);return ok;}

int main(int argc,char**argv){const char*frontier=arg(argc,argv,"--frontier-db"),*address=arg(argc,argv,"--address-db"),*delta_path=arg(argc,argv,"--delta"),*demand=arg(argc,argv,"--scoped-demand"),*frontier_bin=arg(argc,argv,"--scoped-frontier"),*handoffs=arg(argc,argv,"--handoff-dir"),*closure_dir=arg(argc,argv,"--closure-dir"),*conditions=arg(argc,argv,"--condition-db"),*limit_raw=arg(argc,argv,"--limit");sqlite3*d=NULL;sqlite3_stmt*meta=NULL,*q=NULL;char*body=NULL,*delta=NULL;size_t n=0;Closure rows[4096];int count=0,processed=0,already=0,limit=limit_raw?atoi(limit_raw):256;
 enum{SR_REHEAT};static const BfCommandEntry scoped_reheat_commands[]={{"reheat",SR_REHEAT,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(scoped_reheat_commands,sizeof(scoped_reheat_commands)/sizeof(scoped_reheat_commands[0]),argv[1]);
 if(argc<2||!command||command->id!=SR_REHEAT||!frontier||!address||!delta_path||!demand||!frontier_bin||!handoffs||!closure_dir){fputs("usage: bonfyre-scoped-reheat reheat --frontier-db DB --address-db DB --delta JSON --scoped-demand BIN --scoped-frontier BIN --handoff-dir DIR --closure-dir DIR [--condition-db DB] [--limit N]\n",stderr);return 2;}if(limit<1)limit=1;if(limit>4096)limit=4096;if(!ensure_dir(handoffs)||!ensure_dir(closure_dir)||sqlite3_open(frontier,&d)!=SQLITE_OK||!sql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS scoped_reheat_receipt(delta_id TEXT NOT NULL,subject TEXT NOT NULL,scope TEXT NOT NULL,closure_path TEXT NOT NULL,processed_at INTEGER NOT NULL,PRIMARY KEY(delta_id,subject,scope));"))goto fail;if(!(body=read_all(delta_path,&n)))goto fail;
 if(sqlite3_prepare_v2(d,"SELECT json_extract(?1,'$.delta_id')",-1,&meta,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(meta,1,body,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(meta)==SQLITE_ROW&&sqlite3_column_text(meta,0))delta=strdup((const char*)sqlite3_column_text(meta,0));sqlite3_finalize(meta);meta=NULL;if(!delta||!*delta)goto fail;
 if(sqlite3_prepare_v2(d,"WITH writes(ref) AS (SELECT value FROM json_each(?1,'$.writes')) SELECT DISTINCT c.subject,c.scope FROM closure_dependency c JOIN writes w ON w.ref=c.dependency_ref ORDER BY c.subject,c.scope LIMIT ?2",-1,&q,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(q,1,body,(int)n,SQLITE_TRANSIENT);sqlite3_bind_int(q,2,limit);while(sqlite3_step(q)==SQLITE_ROW&&count<4096){const char*s=(const char*)sqlite3_column_text(q,0),*p=(const char*)sqlite3_column_text(q,1);if(!s||!p||snprintf(rows[count].subject,sizeof(rows[count].subject),"%s",s)>=(int)sizeof(rows[count].subject)||snprintf(rows[count].scope,sizeof(rows[count].scope),"%s",p)>=(int)sizeof(rows[count].scope))goto fail;count++;}sqlite3_finalize(q);q=NULL;
 for(int i=0;i<count;i++){char closure[1200],track_out[1240];uint64_t h=hadd(hadd(hadd(1469598103934665603ULL,delta),rows[i].subject),rows[i].scope);if(seen(d,delta,rows[i].subject,rows[i].scope)){already++;continue;}if(snprintf(closure,sizeof(closure),"%s/closure-%016llx.json",closure_dir,(unsigned long long)h)>=(int)sizeof(closure)||snprintf(track_out,sizeof(track_out),"%s.track",closure)>=(int)sizeof(track_out))goto fail;char*base[]={(char*)demand,"dispatch","--db",(char*)address,"--subject",rows[i].subject,"--scope",rows[i].scope,"--dir",(char*)handoffs,NULL};char*with_conditions[]={(char*)demand,"dispatch","--db",(char*)address,"--subject",rows[i].subject,"--scope",rows[i].scope,"--dir",(char*)handoffs,"--condition-db",(char*)conditions,NULL};if(!run_capture(demand,conditions?with_conditions:base,closure))goto fail;char*track[]={(char*)frontier_bin,"track","--db",(char*)frontier,"--address-db",(char*)address,"--closure",closure,NULL};if(!run_capture(frontier_bin,track,track_out)||!add_receipt(d,delta,rows[i].subject,rows[i].scope,closure))goto fail;processed++;}
 fputs("{\"delta_id\":",stdout);jt(delta);printf(",\"affected_closures\":%d,\"processed\":%d,\"already_processed\":%d,\"truth\":\"incremental_respecialization_only\",\"cannot_infer\":[\"reheated closure -> authority\",\"reheated closure -> observation\",\"handoff emitted -> retained body\"]}\n",count,processed,already);sqlite3_close(d);free(body);free(delta);return 0;
fail:sqlite3_finalize(meta);sqlite3_finalize(q);if(d)sqlite3_close(d);free(body);free(delta);return 1;}
